    (OUT / "package-status.json").write_text(json.dumps(status, indent=2) + "\n", encoding="utf-8", newline="\n")

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1100" viewBox="0 0 1600 1100"><style>text{{font-family:Arial,sans-serif;fill:#082b4c;font-size:18px}}.title{{font-size:36px;font-weight:700}}.head{{font-size:24px;font-weight:700}}.warn{{font-size:20px;font-weight:700;fill:#7a3500}}.card{{fill:#f7fbff;stroke:#0b4f8a;stroke-width:3}}.hold{{fill:#fff5d8;stroke:#d59600;stroke-width:3}}.arrow{{stroke:#0b4f8a;stroke-width:5;fill:none;marker-end:url(#a)}}</style><defs><marker id="a" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#0b4f8a"/></marker></defs><rect width="1600" height="1100" fill="#fff"/><text x="60" y="70" class="title">HR-V0 unpowered joint-stack evidence path</text><text x="60" y="112" class="warn">{REVISION} / NO PURCHASE, MOTION OR ENERGIZATION RELEASE</text><rect x="60" y="155" width="430" height="220" rx="16" class="card"/><text x="90" y="205" class="head">1. Receive and quarantine</text><text x="90" y="250">Exact two XM540, two H101, two S102</text><text x="90" y="290">Serials, lots, kit inventory and photographs</text><text x="90" y="330">Reject substitutions and discrepancies</text><path d="M500 265 H575" class="arrow"/><rect x="590" y="155" width="430" height="220" rx="16" class="hold"/><text x="620" y="205" class="head">2. Hard holds before assembly</text><text x="620" y="250">Instrument capability and fixture accepted</text><text x="620" y="290">Screw length/depth/spacers verified</text><text x="620" y="330">Temporary torque instruction signed</text><path d="M1030 265 H1105" class="arrow"/><rect x="1120" y="155" width="420" height="220" rx="16" class="card"/><text x="1150" y="205" class="head">3. Unpowered metrology</text><text x="1150" y="250">Axial stack and attachment geometry</text><text x="1150" y="290">External angle datum and backlash</text><text x="1150" y="330">Point clouds, mass and uncertainty</text><rect x="60" y="440" width="1480" height="470" rx="16" class="card"/><text x="90" y="495" class="head">Evidence boundary</text><text x="90" y="545">HSI-001..006 and HSI-013..014 can close only after received physical execution and qualified acceptance.</text><text x="90" y="590">HSI-007..012 gain geometry screens; final cable, guard, load-path and attachment-use evidence remains external.</text><text x="90" y="635">HSI-015..020 cannot close from a bare joint stack: harness, guard, structural, dynamic, bumper and supplier evidence is still required.</text><text x="90" y="700">No encoder value is read unpowered. No screw enters an actuator until the exact temporary assembly instruction is signed.</text><text x="90" y="745">Hand-positioned poses are measurements only. Never force an angle or use the actuator, cable, connector, case or fixture as a design stop.</text><text x="90" y="805">After measurement: teardown, inspect, re-inventory, re-quarantine, hash the raw evidence, and obtain qualified disposition.</text><text x="90" y="865" class="warn">Current state: 0 of 20 HSI rows closed; 8 hold points open; no physical execution claimed.</text><rect x="60" y="955" width="1480" height="90" rx="16" class="hold"/><text x="90" y="1012" class="warn">Do not order, assemble for use, connect, power, move or energize from this diagram.</text></svg>'''
    (OUT / "HR-V0_joint-stack-metrology.svg").write_text(svg, encoding="utf-8", newline="\n")

    operation_rows = "".join(f'<tr><td>{row["operation_id"]}</td><td>{row["phase"]}</td><td>{row["action"]}</td><td>{row["hsi"]}</td><td>{row["state"]}</td></tr>' for row in OPERATIONS)
    hold_rows = "".join(f'<tr><td>{row["hold_id"]}</td><td>{row["before_operation"]}</td><td>{row["condition"]}</td><td>{row["failure_action"]}</td></tr>' for row in HOLDS)
    hsi_rows = "".join(f'<tr data-route="{row["closure_possible_in_r84"]}"><td>{row["hsi"]}</td><td>{row["r84_route"]}</td><td>{row["operation"]}</td><td>{row["closure_possible_in_r84"]}</td><td>{row["remaining_dependency"]}</td></tr>' for row in HSI_TRACE)
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HR-V0 joint-stack metrology</title><style>:root{{--sky:#66c7f4;--navy:#082b4c;--blue:#0b4f8a;--gold:#f3b61f;--paper:#f7fbff;--hold:#fff5d8}}*{{box-sizing:border-box}}body{{margin:0;font:clamp(16px,1.2vw,19px)/1.55 Arial,sans-serif;color:var(--navy)}}header{{padding:2rem clamp(1rem,5vw,5rem);background:linear-gradient(135deg,var(--sky),#dff5ff);border-bottom:6px solid var(--gold)}}h1{{font-size:clamp(2rem,4vw,4rem);line-height:1.05;margin:.25rem 0 1rem}}h2{{font-size:clamp(1.45rem,2.4vw,2.2rem)}}main{{max-width:1350px;margin:auto;padding:2rem clamp(1rem,4vw,3rem)}}.warning{{font-weight:700;color:#713300;background:var(--hold);border:3px solid var(--gold);padding:1rem;border-radius:.8rem}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:1.25rem}}.card{{border:3px solid var(--blue);border-radius:1rem;padding:1.25rem;background:var(--paper)}}table{{width:100%;border-collapse:collapse;display:block;overflow:auto;margin-bottom:2rem}}th,td{{text-align:left;vertical-align:top;padding:.8rem;border-bottom:1px solid #9db7ca;min-width:145px}}th{{background:var(--navy);color:#fff;position:sticky;top:0}}button{{font:inherit;font-weight:700;color:var(--navy);background:#fff;border:3px solid var(--blue);border-radius:.7rem;padding:.75rem 1rem;margin:.25rem;cursor:pointer}}button[aria-pressed="true"]{{background:var(--gold)}}img{{width:100%;height:auto;border:2px solid #9db7ca}}.meta{{font-size:14px}}[hidden]{{display:none!important}}</style></head><body><header><div class="meta">{REVISION} / R84 controlled package</div><h1>Unpowered J1/J2 acquisition and metrology</h1><div class="warning">{WARNING}. Current state: zero physical articles or measurements accepted.</div></header><main><div class="grid"><section class="card"><h2>What this fixes</h2><p>The earlier plan stopped at “receive and measure.” This package identifies six exact articles, 18 sequenced operations, eight hard holds, six instrument classes, one raw record schema and a direct route for every HSI input.</p></section><section class="card"><h2>Assembly boundary</h2><p>Loose-part receiving and metrology come first. Temporary stack assembly remains blocked until exact screw length, mounting depth, spacer placement, torque, reuse and fixture instructions are signed.</p></section><section class="card"><h2>Power boundary</h2><p>No source-capable equipment, actuator cable or U2D2 may be present. External mechanical angle data replaces the incorrect idea of reading encoder zero while unpowered.</p></section></div><h2>Readable evidence path</h2><img src="HR-V0_joint-stack-metrology.svg" alt="Unpowered joint-stack evidence path"><h2>Hard hold points</h2><table><thead><tr><th>Hold</th><th>Before</th><th>Condition</th><th>Failure action</th></tr></thead><tbody>{hold_rows}</tbody></table><h2>Operation traveler</h2><table><thead><tr><th>Operation</th><th>Phase</th><th>Action</th><th>HSI</th><th>State</th></tr></thead><tbody>{operation_rows}</tbody></table><h2>HSI route</h2><div><button data-filter="ALL" aria-pressed="true">All 20</button><button data-filter="YES">Closable here</button><button data-filter="NO">External dependency</button><button data-filter="SCREEN">Screening/partial</button></div><table><thead><tr><th>HSI</th><th>Input</th><th>Operation</th><th>R84 potential</th><th>Remaining dependency</th></tr></thead><tbody>{hsi_rows}</tbody></table></main><script>const b=[...document.querySelectorAll('button[data-filter]')],r=[...document.querySelectorAll('tbody tr[data-route]')];b.forEach(x=>x.addEventListener('click',()=>{{b.forEach(y=>y.setAttribute('aria-pressed','false'));x.setAttribute('aria-pressed','true');const f=x.dataset.filter;r.forEach(y=>y.hidden=f!=='ALL'&&!y.dataset.route.startsWith(f))}}));</script></body></html>'''
    (OUT / "HR-V0_joint-stack-metrology-guide.html").write_text(html, encoding="utf-8", newline="\n")
    return 0


